import { test, expect } from '@playwright/test';

test.describe('Internal Links Navigation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com');
  });

  test('should open internal link in the same tab', async ({ page }) => {
    await page.getByText('About Us').click();
    expect(page.url()).toBe('https://example.com/about');
  });

  test('should open another internal link in the same tab', async ({ page }) => {
    await page.getByText('Contact').click();
    expect(page.url()).toBe('https://example.com/contact');
  });
});
